-- Run in the Supabase SQL editor. Monetary values are integer kobo.
create type public.user_role as enum ('customer', 'admin', 'operations');
create table public.users (id uuid primary key references auth.users(id) on delete cascade, email text not null, first_name text, last_name text, phone text, role public.user_role not null default 'customer', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, sport_code text not null, description text, image_url text, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, short_description text, description text, sport_code text not null, category_id uuid references public.categories(id), brand_name text, status text not null default 'draft', featured boolean not null default false, seo_title text, seo_description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.product_images (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, url text not null, alt_text text not null, sort_order integer not null default 0, is_primary boolean not null default false);
create table public.product_variants (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, sku text unique not null, variant_name text not null, size text, color text, other_attributes jsonb not null default '{}', selling_price_minor integer not null check (selling_price_minor >= 0), compare_at_price_minor integer, currency text not null default 'NGN', status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customer_addresses (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, label text, recipient_name text not null, phone text not null, country_code text not null default 'NG', region text not null, city text not null, address_line1 text not null, address_line2 text, postal_code text, delivery_notes text, is_default boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), order_number text unique not null, user_id uuid references public.users(id), customer_email text not null, customer_phone text, currency text not null default 'NGN', subtotal_minor integer not null, shipping_minor integer not null default 0, discount_minor integer not null default 0, total_minor integer not null, payment_status text not null default 'PENDING_PAYMENT', fulfillment_status text not null default 'FULFILLMENT_PENDING', shipping_address_snapshot jsonb not null, notes text, created_at timestamptz not null default now(), paid_at timestamptz, updated_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id), product_variant_id uuid references public.product_variants(id), product_name_snapshot text not null, variant_snapshot jsonb not null, quantity integer not null check (quantity > 0), unit_price_minor integer not null, line_total_minor integer not null);
create table public.payments (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), provider text not null default 'paystack', provider_transaction_id text, provider_reference text unique not null, amount_minor integer not null, currency text not null default 'NGN', status text not null, raw_response jsonb, paid_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.suppliers (id uuid primary key default gen_random_uuid(), name text not null, platform_type text, base_url text, integration_type text not null, status text not null default 'active', priority integer not null default 100, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.supplier_products (id uuid primary key default gen_random_uuid(), supplier_id uuid not null references public.suppliers(id), external_product_id text not null, external_variant_id text, title text not null, source_url text, supplier_cost_minor integer not null, supplier_currency text not null default 'NGN', shipping_cost_minor integer not null default 0, availability_status text not null default 'unknown', destination_countries text[] not null default '{}', raw_payload jsonb, last_synced_at timestamptz, unique(supplier_id, external_product_id, external_variant_id));
create table public.product_supplier_mappings (id uuid primary key default gen_random_uuid(), product_variant_id uuid not null references public.product_variants(id), supplier_product_id uuid not null references public.supplier_products(id), priority integer not null default 100, is_preferred boolean not null default false, active boolean not null default true, max_allowed_cost_minor integer, last_verified_at timestamptz);
create table public.supplier_restock_batches (id uuid primary key default gen_random_uuid(), supplier_id uuid not null references public.suppliers(id), batch_reference text not null, sourcing_platform text not null, cif_cost_minor integer not null default 0, duty_minor integer not null default 0, surcharge_minor integer not null default 0, ciss_minor integer not null default 0, etls_minor integer not null default 0, vat_minor integer not null default 0, landed_cost_minor integer not null default 0, currency text not null default 'NGN', status text not null default 'planned', received_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(supplier_id, batch_reference));
create table public.supplier_orders (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), supplier_id uuid not null references public.suppliers(id), supplier_order_reference text, status text not null default 'pending', supplier_total_minor integer, supplier_currency text not null default 'NGN', shipping_method text, tracking_number text, tracking_url text, placed_at timestamptz, confirmed_at timestamptz, raw_response jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(supplier_id, supplier_order_reference));
create table public.shipments (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), supplier_order_id uuid references public.supplier_orders(id), carrier text, tracking_number text, tracking_url text, status text not null default 'pending', shipped_at timestamptz, delivered_at timestamptz, last_synced_at timestamptz);
create table public.agent_tasks (id uuid primary key default gen_random_uuid(), order_id uuid references public.orders(id), task_type text not null, status text not null default 'queued', priority integer not null default 100, input jsonb not null default '{}', output jsonb, error jsonb, attempts integer not null default 0, created_at timestamptz not null default now(), started_at timestamptz, completed_at timestamptz);
create table public.agent_logs (id uuid primary key default gen_random_uuid(), agent_task_id uuid references public.agent_tasks(id), order_id uuid references public.orders(id), event_type text not null, level text not null default 'info', message text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid references public.users(id), order_id uuid references public.orders(id), channel text not null default 'email', template_key text not null, recipient text not null, status text not null, provider_message_id text, sent_at timestamptz, error text, created_at timestamptz not null default now());
create table public.returns (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), status text not null default 'requested', reason text not null, customer_notes text, resolution text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.refunds (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), payment_id uuid not null references public.payments(id), amount_minor integer not null check (amount_minor >= 0), currency text not null default 'NGN', provider_refund_id text unique, status text not null default 'pending', reason text, created_at timestamptz not null default now(), completed_at timestamptz);

alter table public.users enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.product_images enable row level security; alter table public.product_variants enable row level security; alter table public.customer_addresses enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security;
create policy "users read own profile" on public.users for select using (auth.uid() = id);
create policy "customers read own addresses" on public.customer_addresses for select using (auth.uid() = user_id);
create policy "customers manage own addresses" on public.customer_addresses for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "customers read own orders" on public.orders for select using (auth.uid() = user_id);
create policy "catalogue is public" on public.products for select using (status = 'published');
create policy "variants of published products are public" on public.product_variants for select using (exists (select 1 from public.products p where p.id = product_id and p.status = 'published'));
create policy "categories are public" on public.categories for select using (is_active = true);
create policy "images of published products are public" on public.product_images for select using (exists (select 1 from public.products p where p.id = product_id and p.status = 'published'));
